 attributes=[(['Triangle','Square','Circle'],['Straight edges','Curved edge'],[0,0,1]),(['Triangle','Square','Triangle'],['3 sides','4 sides'],[0,1,0]),(['Circle','Square','Circle'],['Corners','No corners'],[1,0,1]),(['Red square','Blue square','Red circle'],['Red','Blue'],[0,1,0]),(['Large leaf','Small leaf','Large flower'],['Large','Small'],[0,1,0]),(['Berry','Leaf','Berry'],['Fruit','Leaves'],[0,1,0])]
