 replace('M11','movement',[choice(f'Face north. Turn {turn}. Which way do you face?',answer,[v for v in ['north','east','south','west'] if v!=answer][:3],[text('North is up; east is right.')],hint='Follow the turn from the starting direction.',representation='grid_path') for turn,answer in [('right','east'),('left','west'),('half a turn','south')]])
