 from .sources import SOURCES
 for facet in ['compare','agreement','reliability']:
  records=[]
  for title,a,b in SOURCES:
   stimuli=[{'kind':'passage','text':a},{'kind':'passage','text':b}]
   if facet=='compare':question='How do the sources differ?';correct='Source A reports a limited observation; Source B promotes a broader promise.';wrong=['Both prove the product works in every situation.','Neither source has a purpose.']
   elif facet=='agreement':question='Which idea is shared by both sources?';correct='A small local test or observation produced a positive result.';wrong=['Every future outcome has already been measured.','No one has observed anything.']
   else:question='Which source gives a clearer basis for checking the claim?';correct='Source A, because it describes its method and limits.';wrong=['Source B, because its headline sounds most certain.','Neither; methods and evidence never matter.']
   records.append(choice(question,correct,wrong,stimuli,hint='Compare author, purpose, evidence and limits.',representation='dual_text_comparison'))
   records.append(choice('Which detail signals the purpose of Source B?','It invites readers to buy a product.',['It reports all possible future results.','It has no intended audience.'],stimuli,hint='Look for what the author wants readers to do.',representation='graphic_organiser'))
  replace('EY401',facet,records)
 for facet in ['synthesise','bias','argument']:
  records=[]
  for title,a,b in SOURCES:
   stimuli=[{'kind':'passage','text':a+'\n\n'+b}]
   if facet=='synthesise':question='What conclusion follows when both sources are considered?';correct='The small observation is useful but does not establish the advertised guarantee.';wrong=['The guarantee is proved by enthusiastic wording.','There is no useful information in either source.']
   elif facet=='bias':question='What could influence the presentation in Source B?';correct='The seller benefits if readers buy the product.';wrong=['The seller has measured every possible outcome.','All positive language is automatically false.']
   else:question='Which evidence would strengthen the broad claim?';correct='Independent tests with more examples and a wider range of conditions.';wrong=['A larger headline repeating the promise.','More colourful pictures without test details.']
   records.append(choice(question,correct,wrong,stimuli,hint='Separate recorded observations from claims that go beyond them.',representation='text_passage'))
   records.append(choice('Why do the limits in Source A matter?','They show which conclusions the observations can support.',['They prove the observations are worthless.','They mean a promise can replace evidence.'],stimuli,hint='A clear limit helps readers assess the strength of the evidence.',representation='graphic_organiser'))
  replace('EY504',facet,records)
 # Add informational genre examples alongside the existing narratives in Year 2.
 information=[('Bird visits','Ella counted bird visits for five mornings. She watched for ten minutes each day. Her notes showed twenty visits altogether. The same bird might have visited more than once, so twenty visits did not necessarily mean twenty different birds. Ella kept the bowl in a quiet shaded place. An adult cleaned it each evening and replaced the water. Ella planned to watch for another week. She wanted to learn whether different weather or times of day affected the visits. A short record can help people ask better questions, but it cannot tell them everything.', 'Twenty visits may include repeat visits by the same bird.'),('A handle trial','A garden group tested three gate handles with eight volunteers. They recorded whether people could reach and grip each handle. The first handle caught on one sleeve. Two people found the second handle hard to grip. Everyone in this small group managed to use the third handle. The group chose it for a longer trial, rather than calling it perfect for everyone. They still wanted to test it in wet weather and invite more visitors. Their notes explained the method and the limits. Readers could use those details to decide what should be tested next.', 'A larger trial could include more users and wet weather.'),('Paper covers','A craft group tested four folded lantern covers and four patchwork covers. They used dry paper and the same frame size. Each cover stood beside the same fan for three minutes. One folded cover tore, while none of the patchwork covers tore during the test. The patchwork covers also took longer to make and used more tape. The group recorded these differences. They did not claim that any cover would last forever. More examples and different conditions would help them learn about durability. A short material test gives evidence for a limited conclusion.', 'A short test cannot prove that every cover lasts forever.')]
 for facet in ['inference','purpose','evidence']:
  e=next(e for e in SKILLS['EY202'] if e['id'].endswith('.'+facet))
  for title,body,conclusion in information:
   assert 80<=len(body.split())<=200
   e['items'].append(choice('What is the purpose of this informational text?' if facet=='purpose' else 'Which conclusion is supported by the text?', 'To explain observations and their limits' if facet=='purpose' else conclusion,['To advertise a guaranteed result','To prove that no more questions are needed'],[{'kind':'passage','text':body}],hint='Use the information and limits stated in the text.',representation='short_text'))
   e['items'].append(choice('Why would more observations be useful?','They could check whether the same result occurs in other conditions.',['They would make the original observations disappear.','They would guarantee a preferred answer.'],[{'kind':'passage','text':body}],representation='multiple_choice'))
